#nullable enable
namespace YuzeToolkit.Eval.Broker;

internal static class WorkspaceStatusPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Yuze Eval Tool · Remote connections</title>
<style>body{font:16px/1.6 system-ui;margin:0;background:#f3f6f2;color:#19382e}main{max-width:900px;margin:48px auto;padding:0 24px}h1{font-size:30px;margin:0}p{color:#52685e}button{background:#185d45;color:white;border:0;border-radius:8px;padding:10px 16px;font:inherit;cursor:pointer}.state{padding:14px 18px;background:white;border:1px solid #cad8ce;border-radius:10px;margin:18px 0}.offline{color:#9b302a;border-color:#db9a94;background:#fff0ee}table{width:100%;border-collapse:collapse;background:white}td,th{padding:13px;text-align:left;border-bottom:1px solid #dde6df}#events{max-height:320px;overflow:auto;padding-left:24px}small{color:#52685e}code{overflow-wrap:anywhere}</style>
<main><h1>Remote connections</h1><p>Keep this page open to see connection changes. Desktop notifications are optional. This page cannot wake an idle AI conversation.</p><button id="notify">Enable desktop notifications</button><div id="state" class="state" role="status" aria-live="polite">Connecting…</div><table><thead><tr><th>Computer</th><th>Connection</th><th>Shared projects</th></tr></thead><tbody id="hosts"></tbody></table><h2>Recent changes</h2><ol id="events" aria-live="polite"></ol><small>Only configured remote computers are shown. Reconnect a workspace after its Broker restarts; check actual results before retrying an interrupted write.</small></main>
<script>
let sid=null,seq=0,previous=new Map(),first=true;const state=document.getElementById('state'),events=document.getElementById('events');
document.getElementById('notify').onclick=async()=>{if(!('Notification'in window)){state.textContent='This browser does not support desktop notifications.';return;}const p=await Notification.requestPermission();document.getElementById('notify').textContent=p==='granted'?'Desktop notifications enabled':'Desktop notifications unavailable';};
function note(text){const li=document.createElement('li');li.textContent=new Date().toLocaleTimeString()+' · '+text;events.prepend(li);while(events.children.length>100)events.lastChild.remove();if('Notification'in window&&Notification.permission==='granted')new Notification('Yuze Eval Tool',{body:text});}
async function rpc(method,params={}){const h={'Content-Type':'application/json','Accept':'application/json, text/event-stream'};if(sid)h['Mcp-Session-Id']=sid;const r=await fetch('/remote/mcp',{method:'POST',headers:h,body:JSON.stringify({jsonrpc:'2.0',id:++seq,method,params}),signal:AbortSignal.timeout(15000)});if(!r.ok){if(r.status===404)sid=null;throw Error('Broker connection unavailable ('+r.status+')');}sid=r.headers.get('Mcp-Session-Id')||sid;const data=await r.json();if(data.error)throw Error(data.error.message);return data.result;}
async function refresh(){try{if(!sid)await rpc('initialize',{protocolVersion:'2025-11-25',capabilities:{},clientInfo:{name:'YuzeEvalTool.ConnectionMonitor',version:'1'}});const response=await rpc('tools/call',{name:'workspace_list',arguments:{}});if(response.isError)throw Error(response.content[0].text);const data=response.structuredContent.result;const next=new Map();for(const host of data.hosts)next.set(host.hostId,{state:host.state,error:host.error});for(const e of data.errors)next.set(e.hostId,{state:'unavailable',error:e.error});const body=document.getElementById('hosts');body.replaceChildren();let unavailable=0;for(const[id,h]of next){const tr=document.createElement('tr');const count=data.projects.filter(p=>p.hostId===id).length;for(const value of[id,h.state+(h.error?' · '+h.error:''),String(count)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);if(h.state!=='online'){unavailable++;tr.className='offline';}if(!first&&previous.get(id)?.state!==h.state)note(id+': '+h.state+(h.error?' ('+h.error+')':''));}state.textContent=next.size===0?'No remote workspaces configured.':unavailable?unavailable+' remote connection(s) need attention.':'All '+next.size+' remote connections are online.';state.className='state'+(unavailable?' offline':'');previous=next;first=false;}catch(e){if(!state.classList.contains('offline'))note(e.message);state.className='state offline';state.textContent=e.message+' · Retrying; displayed project data may be stale.';}finally{setTimeout(refresh,3000);}}refresh();
</script></html>
""";
}
